import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost:
        "text-foreground hover:bg-muted data-[pressed]:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ duration: 0.14, ease: [0.23, 1, 0.32, 1] }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import {
  DateSegment as AriaDateSegment,
  composeRenderProps,
  type DateSegmentProps,
} from "react-aria-components";
import { cn } from "./utils";

/** Keep the active segment legible across date and time fields and pickers. */
export function DateSegment({ className, ...props }: DateSegmentProps) {
  return (
    <AriaDateSegment
      {...props}
      data-slot="date-segment"
      className={composeRenderProps(className, (className) =>
        cn(
          "rounded-md px-1 py-0.5 tabular-nums outline-none caret-transparent data-[placeholder]:text-muted-foreground data-[invalid]:text-destructive [&[data-type=literal]]:px-0 [&:focus]:bg-primary [&:focus]:text-primary-foreground forced-colors:[&:focus]:bg-[Highlight] forced-colors:[&:focus]:text-[HighlightText]",
          className,
        ),
      )}
    />
  );
}

// Shared field styles keep standalone inputs and segmented date/time controls in sync.
export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none placeholder:text-muted-foreground/80 hover:border-primary/45 motion-safe:transition-[border-color,box-shadow] motion-safe:duration-150 data-[focus-visible]:border-ring data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50 data-[invalid]:border-destructive data-[invalid]:ring-3 data-[invalid]:ring-destructive/20 data-[invalid]:hover:border-destructive data-[invalid]:data-[focus-visible]:border-destructive data-[invalid]:data-[focus-visible]:ring-destructive/30 read-only:bg-muted/40 read-only:hover:border-input data-[disabled]:cursor-not-allowed data-[disabled]:bg-muted data-[disabled]:opacity-60 data-[disabled]:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] hover:border-primary/45 has-[[data-focus-visible]]:border-ring has-[[data-focus-visible]]:ring-3 has-[[data-focus-visible]]:ring-ring/50 group-data-[invalid]:border-destructive group-data-[invalid]:hover:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-data-[disabled]:bg-muted group-data-[disabled]:opacity-60 group-data-[disabled]:hover:border-input motion-safe:transition-[border-color,box-shadow] motion-safe:duration-150";

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { cn } from "./utils";

function edgeOffset(placement: string | null) {
  switch (placement) {
    case "top":
      return { x: 0, y: 5 };
    case "left":
      return { x: 5, y: 0 };
    case "right":
      return { x: -5, y: 0 };
    default:
      return { x: 0, y: -5 };
  }
}

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { ...edgeOffset(placement), scale: 0.98 }
            }
            animate={
              isExiting && !reduceMotion
                ? { ...edgeOffset(placement), scale: 0.99 }
                : { x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: isExiting ? 0.14 : 0.2,
              ease: [0.23, 1, 0.32, 1],
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none transition-opacity duration-100 data-[entering]:opacity-0 data-[exiting]:opacity-0 motion-safe:duration-200 motion-safe:data-[exiting]:duration-150 data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import {
  Calendar as AriaCalendar,
  CalendarCell,
  CalendarGrid,
  CalendarHeading,
  type CalendarProps,
  composeRenderProps,
  type DateValue,
} from "react-aria-components";
import { ChevronLeft, ChevronRight } from "reicon-react";
import { cn } from "./utils";
import { Button } from "./button";

export const calendarCellBaseClass =
  "grid size-11 cursor-pointer place-items-center text-sm tabular-nums outline-none hover:bg-muted data-[focused]:bg-muted data-[outside-month]:text-muted-foreground/50 data-[unavailable]:cursor-not-allowed data-[unavailable]:bg-muted data-[unavailable]:text-muted-foreground data-[unavailable]:line-through data-[unavailable]:hover:bg-muted data-[disabled]:cursor-default data-[disabled]:bg-muted data-[disabled]:text-muted-foreground data-[disabled]:opacity-60 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-[-2px] data-[focus-visible]:outline-ring";

export const calendarCellClass = `${calendarCellBaseClass} rounded-md data-[selected]:bg-primary data-[selected]:text-primary-foreground`;

export function Calendar<T extends DateValue>({
  className,
  children,
  ...props
}: CalendarProps<T> & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaCalendar
      {...props}
      data-slot="calendar"
      className={composeRenderProps(className, (className) =>
        cn("w-fit max-w-full text-foreground", className),
      )}
    >
      {children ?? (
        <>
          <div className="mb-3 flex items-center justify-between gap-2">
            <Button
              slot="previous"
              aria-label="Previous month"
              variant="ghost"
              size="icon"
            >
              <ChevronLeft size={17} aria-hidden="true" />
            </Button>
            <CalendarHeading className="text-sm font-semibold" />
            <Button
              slot="next"
              aria-label="Next month"
              variant="ghost"
              size="icon"
            >
              <ChevronRight size={17} aria-hidden="true" />
            </Button>
          </div>
          <CalendarGrid
            className="border-separate border-spacing-0 text-center text-xs"
            weekdayStyle="short"
          >
            {(date) => (
              <CalendarCell date={date} className={calendarCellClass} />
            )}
          </CalendarGrid>
        </>
      )}
    </AriaCalendar>
  );
}

"use client";

import {
  RangeCalendar as AriaRangeCalendar,
  CalendarCell,
  CalendarGrid,
  CalendarHeading,
  composeRenderProps,
  type DateValue,
  type RangeCalendarProps,
} from "react-aria-components";
import { ChevronLeft, ChevronRight } from "reicon-react";
import { cn } from "./utils";
import { Button } from "./button";
import { calendarCellBaseClass } from "./calendar";

export function RangeCalendar<T extends DateValue>({
  className,
  children,
  ...props
}: RangeCalendarProps<T> & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaRangeCalendar
      {...props}
      data-slot="range-calendar"
      className={composeRenderProps(className, (className) =>
        cn("w-fit max-w-full text-foreground", className),
      )}
    >
      {children ?? (
        <>
          <div className="mb-3 flex items-center justify-between gap-2">
            <Button
              slot="previous"
              aria-label="Previous month"
              variant="ghost"
              size="icon"
            >
              <ChevronLeft size={17} aria-hidden="true" />
            </Button>
            <CalendarHeading className="text-sm font-semibold" />
            <Button
              slot="next"
              aria-label="Next month"
              variant="ghost"
              size="icon"
            >
              <ChevronRight size={17} aria-hidden="true" />
            </Button>
          </div>
          <CalendarGrid
            className="border-separate border-spacing-0 text-center text-xs"
            weekdayStyle="short"
          >
            {(date) => (
              <CalendarCell
                date={date}
                className={cn(
                  calendarCellBaseClass,
                  "rounded-md data-[selected]:rounded-none data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[selected]:hover:bg-accent data-[selected]:data-[focused]:bg-accent data-[selected]:[td:first-child_&]:rounded-s-md data-[selected]:[td:last-child_&]:rounded-e-md data-[selection-start]:rounded-s-md data-[selection-start]:bg-primary data-[selection-start]:text-primary-foreground data-[selection-start]:hover:bg-primary data-[selection-start]:data-[focused]:bg-primary data-[selection-end]:rounded-e-md data-[selection-end]:bg-primary data-[selection-end]:text-primary-foreground data-[selection-end]:hover:bg-primary data-[selection-end]:data-[focused]:bg-primary",
                )}
              />
            )}
          </CalendarGrid>
        </>
      )}
    </AriaRangeCalendar>
  );
}

"use client";

import {
  DateRangePicker as AriaDateRangePicker,
  composeRenderProps,
  DateInput,
  type DateRangePickerProps,
  type DateValue,
  FieldError,
  Group,
  Label,
  Text,
} from "react-aria-components";
import { ChevronDown } from "reicon-react";
import { cn } from "./utils";
import { Button } from "./button";
import { DateSegment } from "./date-segment";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldLabelStyles,
  segmentedFieldStyles,
} from "./field-styles";
import { Popover } from "./popover";
import { RangeCalendar } from "./range-calendar";

export function DateRangePicker<T extends DateValue>({
  className,
  label,
  description,
  children,
  ...props
}: DateRangePickerProps<T> &
  React.RefAttributes<HTMLDivElement> & {
    label?: string;
    description?: string;
  }) {
  return (
    <AriaDateRangePicker
      {...props}
      data-slot="date-range-picker"
      className={composeRenderProps(className, (className) =>
        cn("group grid gap-2 data-[focus-visible]:outline-none", className),
      )}
    >
      {children ?? (
        <>
          {label && (
            <Label
              data-slot="date-range-picker-label"
              className={fieldLabelStyles}
            >
              {label}
            </Label>
          )}
          <Group
            data-slot="date-range-picker-group"
            className={cn(
              segmentedFieldStyles,
              "data-[focus-visible]:outline-none",
            )}
          >
            <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-1 px-3 py-2 text-sm">
              <DateInput
                slot="start"
                data-slot="date-range-picker-start"
                className="flex items-center data-[focus-visible]:outline-none"
              >
                {(segment) => <DateSegment segment={segment} />}
              </DateInput>
              <span aria-hidden="true" className="text-muted-foreground">
                –
              </span>
              <DateInput
                slot="end"
                data-slot="date-range-picker-end"
                className="flex items-center data-[focus-visible]:outline-none"
              >
                {(segment) => <DateSegment segment={segment} />}
              </DateInput>
            </div>
            <Button
              aria-label="Choose date range"
              data-slot="date-range-picker-trigger"
              variant="ghost"
              size="icon"
              className="me-1 shrink-0"
            >
              <ChevronDown size={17} aria-hidden="true" />
            </Button>
          </Group>
          {description && (
            <Text
              slot="description"
              data-slot="date-range-picker-description"
              className={fieldDescriptionStyles}
            >
              {description}
            </Text>
          )}
          <FieldError
            data-slot="date-range-picker-error"
            className={fieldErrorStyles}
          />
          <Popover data-slot="date-range-picker-popover" className="p-3">
            <RangeCalendar />
          </Popover>
        </>
      )}
    </AriaDateRangePicker>
  );
}
